    @Id @Column(name = "trade_id") private String tradeId;
    @Column(name = "account_id") private String accountId;
    private String symbol;
    private String side;
    private int quantity;
    private BigDecimal price;
    private String status;
    @Column(name = "trade_date") private LocalDate tradeDate;

    protected Trade() {}

    public BigDecimal getAmount() { return price.multiply(BigDecimal.valueOf(quantity)); }
    public boolean isSettled() { return "SETTLED".equals(status); }

    public String getTradeId() { return tradeId; }
    public String getAccountId() { return accountId; }
    public String getSymbol() { return symbol; }
    public String getSide() { return side; }
    public int getQuantity() { return quantity; }
    public BigDecimal getPrice() { return price; }
    public String getStatus() { return status; }
}
