// ─── File: src/main/java/com/bank/recon/service/ReconciliationService.java ───
package com.bank.recon.service;

import com.bank.recon.dto.ReconciliationReport;
import com.bank.recon.model.Trade;
import com.bank.recon.repository.TradeRepository;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.math.BigDecimal;
import java.util.*;
import java.util.stream.Collectors;

@Service
@RequiredArgsConstructor
@Slf4j
public class ReconciliationService {

    private final TradeRepository tradeRepo;

    @Transactional(readOnly = true)
    public ReconciliationReport reconcile() {
        List<Trade> trades = tradeRepo.findAll();

        // ═══ 1. COUNT — how many settled trades? ═══
        long totalSettled = trades.stream()
            .filter(Trade::isSettled)
            .count();
        log.info("[count()] Settled trades: {}", totalSettled);

        // ═══ 2. REDUCE — total settled amount ═══
        BigDecimal settledAmount = trades.stream()
            .filter(Trade::isSettled)
            .map(Trade::getAmount)
            .reduce(BigDecimal.ZERO, BigDecimal::add);
        log.info("[reduce()] Total settled: Rs.{}", settledAmount);

        // ═══ 3. MAX — largest single trade amount ═══
        BigDecimal largestTrade = trades.stream()
            .map(Trade::getAmount)
            .max(Comparator.naturalOrder())          // returns Optional<BigDecimal>
            .orElse(BigDecimal.ZERO);
        log.info("[max()] Largest trade: Rs.{}", largestTrade);

        // ═══ 4. FINDFIRST — first settled trade for audit trail ═══
        String firstSettledId = trades.stream()
            .filter(Trade::isSettled)
            .findFirst()                              // SHORT-CIRCUIT! Stops after first match
            .map(Trade::getTradeId)
            .orElse("NONE");
        log.info("[findFirst()] First settled: {}", firstSettledId);

        // ═══ 5. ANYMATCH — any failed trades? (short-circuit boolean) ═══
        boolean hasFailedTrades = trades.stream()
            .anyMatch(t -> "FAILED".equals(t.getStatus()));
        log.info("[anyMatch()] Has failed: {}", hasFailedTrades);

        // ═══ 6. ALLMATCH — are all trades settled? ═══
        boolean allSettled = trades.stream()
            .allMatch(Trade::isSettled);
        log.info("[allMatch()] All settled: {}", allSettled);

        // ═══ 7. COLLECT(groupingBy) — count per symbol ═══
        Map<String, Long> countBySymbol = trades.stream()
            .filter(Trade::isSettled)
            .collect(Collectors.groupingBy(Trade::getSymbol, Collectors.counting()));
        log.info("[groupingBy()] By symbol: {}", countBySymbol);

        // ═══ 8. COLLECT(toMap) — total amount per symbol ═══
        Map<String, BigDecimal> amountBySymbol = trades.stream()
            .filter(Trade::isSettled)
            .collect(Collectors.toMap(
                Trade::getSymbol,
                Trade::getAmount,
                BigDecimal::add));  // merge function for duplicate keys
        log.info("[toMap()] Amount by symbol: {}", amountBySymbol);

        // ═══ 9. COLLECT(partitioningBy) — settled vs unsettled ═══
        Map<Boolean, Long> settledVsUnsettled = trades.stream()
            .collect(Collectors.partitioningBy(Trade::isSettled, Collectors.counting()));
        log.info("[partitioningBy()] Settled/unsettled: {}", settledVsUnsettled);

        // ═══ 10. COLLECT(joining) — CSV of unique symbols ═══
        String symbolsCsv = trades.stream()
            .filter(Trade::isSettled)
            .map(Trade::getSymbol)
            .distinct()
            .sorted()
            .collect(Collectors.joining(", "));
        log.info("[joining()] Symbols: {}", symbolsCsv);

        // ═══ 11. FOREACH — notify (void return) ═══
        trades.stream()
            .filter(t -> "FAILED".equals(t.getStatus()))
            .forEach(t -> log.warn("[forEach()] ⚠ FAILED trade alert: {} {}",
                t.getTradeId(), t.getSymbol()));

        return new ReconciliationReport(
            totalSettled, settledAmount, largestTrade, firstSettledId,
            hasFailedTrades, allSettled, countBySymbol, amountBySymbol,
            settledVsUnsettled, symbolsCsv,
            "count, reduce, max, findFirst, anyMatch, allMatch, groupingBy, toMap, partitioningBy, joining, forEach"
        );
    }
}
```

