// ─── File: src/test/java/com/bank/recon/service/TerminalOpsTest.java ───
package com.bank.recon.service;

import org.junit.jupiter.api.Test;
import java.math.BigDecimal;
import java.util.*;
import java.util.stream.*;
import static org.assertj.core.api.Assertions.*;

class TerminalOpsTest {

    // ═══ COLLECT — toList, toSet, toMap, groupingBy, joining ═══
    @Test
    void collectToListAndSet() {
        List<String> list = Stream.of("RELIANCE", "TCS", "RELIANCE")
            .collect(Collectors.toList());
        assertThat(list).hasSize(3);  // duplicates kept

        Set<String> set = Stream.of("RELIANCE", "TCS", "RELIANCE")
            .collect(Collectors.toSet());
        assertThat(set).hasSize(2);  // duplicates removed
    }

    @Test
    void collectGroupingBy() {
        Map<String, Long> grouped = Stream.of("BUY", "SELL", "BUY", "BUY", "SELL")
            .collect(Collectors.groupingBy(s -> s, Collectors.counting()));
        assertThat(grouped).containsEntry("BUY", 3L).containsEntry("SELL", 2L);
    }

    @Test
    void collectToMapWithMerge() {
        // Without merge: duplicate keys → IllegalStateException!
        // With merge function: handles duplicates
        Map<String, Integer> merged = Stream.of("RELIANCE", "TCS", "RELIANCE")
            .collect(Collectors.toMap(s -> s, String::length, Integer::sum));
        assertThat(merged).containsEntry("RELIANCE", 16);  // 8+8
    }

    @Test
    void collectJoining() {
        String csv = Stream.of("RELIANCE", "TCS", "HDFC")
            .collect(Collectors.joining(", ", "[", "]"));
        assertThat(csv).isEqualTo("[RELIANCE, TCS, HDFC]");
    }

    @Test
    void collectPartitioningBy() {
        Map<Boolean, List<Integer>> partitioned = Stream.of(780, 580, 650, 490, 750)
            .collect(Collectors.partitioningBy(s -> s >= 650));
        assertThat(partitioned.get(true)).containsExactly(780, 650, 750);
        assertThat(partitioned.get(false)).containsExactly(580, 490);
    }

    // ═══ REDUCE ═══
    @Test
    void reduceWithIdentity() {
        BigDecimal total = Stream.of("100", "200", "300")
            .map(BigDecimal::new)
            .reduce(BigDecimal.ZERO, BigDecimal::add);
        assertThat(total).isEqualByComparingTo("600");
    }

    @Test
    void reduceWithoutIdentityReturnsOptional() {
        Optional<BigDecimal> max = Stream.of("100", "300", "200")
            .map(BigDecimal::new)
            .reduce(BigDecimal::max);
        assertThat(max).contains(new BigDecimal("300"));

        Optional<BigDecimal> empty = Stream.<BigDecimal>empty().reduce(BigDecimal::max);
        assertThat(empty).isEmpty();  // empty stream → empty Optional
    }

    // ═══ SHORT-CIRCUIT TERMINALS ═══
    @Test
    void findFirstStopsEarly() {
        Optional<String> first = Stream.of("low", "low", "HIGH", "HIGH")
            .filter(s -> s.equals("HIGH"))
            .findFirst();
        assertThat(first).contains("HIGH");
    }

    @Test
    void anyMatchStopsOnFirstTrue() {
        boolean found = Stream.of(500, 600, 1500000, 700)
            .anyMatch(n -> n > 1000000);
        assertThat(found).isTrue();
    }

    @Test
    void allMatchStopsOnFirstFalse() {
        boolean all = Stream.of(780, 650, 490, 750)
            .allMatch(s -> s >= 650);
        assertThat(all).isFalse();  // 490 < 650 → false, stops
    }

    @Test
    void noneMatchStopsOnFirstTrue() {
        boolean none = Stream.of("SETTLED", "SETTLED", "FAILED")
            .noneMatch(s -> s.equals("FAILED"));
        assertThat(none).isFalse();  // found FAILED → false
    }

    // ═══ STREAM CONSUMED AFTER TERMINAL ═══
    @Test
    void streamCannotBeReusedAfterTerminal() {
        Stream<String> stream = Stream.of("A", "B", "C");
        stream.count();  // terminal → consumed

        assertThatThrownBy(() -> stream.toList())
            .isInstanceOf(IllegalStateException.class);
    }

    // ═══ FOREACH — void return ═══
    @Test
    void forEachExecutesAction() {
        List<String> collected = new ArrayList<>();
        Stream.of("RELIANCE", "TCS").forEach(collected::add);
        assertThat(collected).containsExactly("RELIANCE", "TCS");
    }
}
